--
-- Table structure for table `payment`
--

DROP TABLE IF EXISTS `payment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment` (
  `id` int NOT NULL AUTO_INCREMENT,
  `order_id` int NOT NULL,
  `provider` enum('MOCK','VNPAY') NOT NULL,
  `status` enum('PENDING','SUCCEEDED','FAILED') NOT NULL DEFAULT 'PENDING',
  `amount` int NOT NULL,
  `txn_ref` varchar(50) NOT NULL,
  `provider_txn_no` varchar(64) DEFAULT NULL,
  `bank_code` varchar(20) DEFAULT NULL,
  `pay_date` datetime(3) DEFAULT NULL,
  `raw_response` json DEFAULT NULL,
  `failure_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `payment_txn_ref_key` (`txn_ref`),
  KEY `payment_order_id_idx` (`order_id`),
  CONSTRAINT `payment_order_id_fkey` FOREIGN KEY (`order_id`) REFERENCES `order` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=74 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

